overviews = [load_overview(path) for path in paths]

def _four_qualities(overview):
    return (
        overview["product"]["quality"],
        overview["substrate"]["quality"],
        overview["crosspoint"]["trend"]["quality"],
        overview["quality"],
    )

changes = []
regressed = 0
worst_item = None
worst_count = -1
for i in range(1, len(overviews)):
    previous_qualities = _four_qualities(overviews[i - 1])
    qualities = _four_qualities(overviews[i])
    regressions = tuple(
        previous == "pass" and current == "fail"
        for previous, current in zip(previous_qualities, qualities)
    )
    item_regressions = sum(1 for flag in regressions if flag)
    item_quality = "fail" if item_regressions else "pass"
    if item_regressions:
        regressed += 1

    item = {
        "index": int(i),
        "qualities": qualities,
        "regressions": regressions,
        "quality": item_quality,
    }
    changes.append(item)

    if item_regressions > worst_count:
        worst_count = item_regressions
        worst_item = item

